SELECT FROM customer c INNER JOIN employee e ON e.employee_id = c.assigned_sales_id WHERE c.active = TRUE AND c.status != 'INACTIVE'
AND ( c.customer_name LIKE CONCAT(#{keyword}, '%') OR c.business_registration_no LIKE CONCAT(#{keyword}, '%') )
ORDER BY c.customer_name ASC, c.customer_id ASC LIMIT #{limit}

SELECT COUNT(*)
FROM customer
WHERE business_registration_no = #{businessRegistrationNo}
  AND customer_id != #{customerId}
